    pass

gsl_combination_alloc.argtypes = [ctypes.c_int, ctypes.c_int]
gsl_combination_init_first.argtypes = [ctypes.POINTER(gsl_combination), ctypes.c_int, ctypes.c_int]
gsl_combination_free.argtypes = [ctypes.POINTER(gsl_combination)]

def create_first_combination(n, k):
    comb = gsl_combination_alloc(n, k)
    if not comb:
        return None
    gsl_combination_init_first(comb, n, k)
    data = list(comb.vector[:])
    gsl_combination_free(comb)
    return data

