def create_combination(n, k):
    combination = libgslcblas.gsl_combination_alloc(n, k)
    if combination:
        libgslcblas.gsl_combination_init_first(combination)
        result = []
        for i in range(k):
            result.append(libgslcblas.gsl_combination_get_element(combination, i))
