    if len(weights) != len(data):
        raise ValueError("Weights and data must have the same length")
    result = gsl.gsl_stats_wmean(
        (ctypes.c_double * len(weights))(*weights),
        (ctypes.c_double * len(data))(*data),
        ctypes.c_size_t(len(weights)),
