    rows = len(c_matrix)
    cols = len(c_matrix[0])
    matrix = gsl_matrix_complex_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            matrix.values[i][j] = gsl_complex(c_matrix[i][j].real, c_matrix[i][j].imag)
    return matrix

