    ev_list = [ev.get(i) for i in range(len(ev))]
    ev_list = [(complex(num.real, num.imag), complex(imag.real, imag.imag)) for num, imag in zip(ev_list, EV)]
    return (ev_list, [[(EV[i].get(j).real, EV[i].get(j).imag) for j in range(len(EV[0]))] for i in range(len(EV))])

