class RingBuf:
    def __init__(self, size):
        self.ringbuf = gsl.gsl_ring_buffer_alloc(size)
def initialize_ringbuf(self, size):
    return self

def insert_into_ringbuf(self, ringbuf, values):
    for value in values:
        ringbuf.ringbuf_insert(ringbuf.ringbuf, ctypes.byref(value))
def copy_ringbuf_to_list(self, ringbuf):
    result = [0] * ringbuf.ringbuf_size(ringbuf.ringbuf)
    for i in range(ringbuf.ringbuf_used(ringbuf.ringbuf)):
        result[i] = ringbuf.ringbuf_read(ringbuf.ringbuf, i)
    return result
