class GslRstatQuantileWorkspace(c_void_p):
    def __init__(self):
        self.value = c_double()
        selfworkspace_ptr = ctypes.pointer(self)

    @classmethod
    def alloc(cls, size):
        return cls(gsl.gsl_rstat_quantile_alloc(size))

    def reset(self):
        gsl.gsl_rstat_quantile_reset(ctypes.byref(self), ctypes.c_int(0))

    @staticmethod
    def add(workspace, x):
        workspace.value = x
        gsl.gsl_rstat_quantile_add(ctypes.byref(workspace))

    def get(self, p):
        ret = c_double()
        gsl.gsl_rstat_quantile_get(ctypes.byref(ret), ctypes.c_double(p), ctypes.byref(workspace_ptr=ctypes.pointer(self)))
        return ret.value

    def free(self):
        if self:
            gsl.gsl_rstat_quantile_free(self)

def compute_quantile(p, values):
    workspace = GslRstatQuantileWorkspace.alloc(len(values))
    try:
        for value in values:
            GslRstatQuantileWorkspace.add(workspace, value)
        quantile_value = workspace.get(p)
        return quantile_value
    finally:
        GslRstatQuantileWorkspace.free(workspace)

