class SaxpyError(Exception):
    pass

def saxpy(N, alpha, X, incX, Y, incY):
    X = (ctypes.c_float * (N + 1))(*X[:incX*(N//incX)] + (ctypes.c_float * ((N + 1) % incX))())
    Y = (ctypes.c_float * (N + 1))(*Y[:incY*(N//incY)] + (ctypes.c_float * ((N + 1) % incY))())
    try:
        cblas.saxpy(ctypes.byref(ctypes.c_int(N)), ctypes.c_float(alpha), X, ctypes.c_int(incX), Y, ctypes.c_int(incY))
    except AttributeError:
        raise SaxpyError(\"Could not find the CBLAS saxpy routine\")
    return list(Y[:N:incY])

